import { Group, Mesh, PlaneGeometry, Texture, MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial, DirectionalLight, Color, DoubleSide } from 'three/webgpu';
import { texture, uv, positionLocal, normalLocal, uniform, vec2, length, smoothstep, float } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitivesLib from '@/primitives';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const GroupCtor = THREE?.Group || Group;
  const root = new GroupCtor();
  root.name = 'stat-tile-features';

  const wrapper = new GroupCtor();
  root.add(wrapper);

  const colors = config?.intent?.visualSpec?.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const CARD_W = 1.3;
  const CARD_H = 0.85;

  // ---------------------------------------------------------------
  // DEPTH PLANE 1 — machined metal backdrop plate
  // ---------------------------------------------------------------
  const plateGeo = new PlaneGeometry(CARD_W + 0.12, CARD_H + 0.12, 1, 1);
  const plateMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.ink),
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
    side: DoubleSide,
  });
  const plate = new Mesh(plateGeo, plateMat);
  plate.position.z = -0.05;
  wrapper.add(plate);

  // ---------------------------------------------------------------
  // DEPTH PLANE 2 — tessellated parallax-displaced subject plane
  // ---------------------------------------------------------------
  const parallaxGeo = new PlaneGeometry(CARD_W, CARD_H, 64, 64);
  const parallaxMat = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.35,
    side: DoubleSide,
  });

  const placeholderColorTex = new THREE.Texture();
  const placeholderDepthTex = new THREE.Texture();
  const colorTexNode = texture(placeholderColorTex);
  const depthTexNode = texture(placeholderDepthTex);
  const displacementScale = uniform(float(0.06));

  parallaxMat.colorNode = colorTexNode;
  parallaxMat.positionNode = positionLocal.add(
    normalLocal.mul(depthTexNode.r.mul(displacementScale))
  );

  const parallaxMesh = new Mesh(parallaxGeo, parallaxMat);
  parallaxMesh.position.z = 0.0;
  wrapper.add(parallaxMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      colorTexNode.value = tex;
      parallaxMat.needsUpdate = true;
    }).catch(() => {});
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthTexNode.value = tex;
      parallaxMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---------------------------------------------------------------
  // DEPTH PLANE 3 — foreground accent edge (focus / hover indicator)
  // ---------------------------------------------------------------
  const edgeGeo = new PlaneGeometry(CARD_W + 0.16, 0.045, 1, 1);
  const edgeMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent),
    transparent: true,
    opacity: 0.28,
  });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.set(0, -(CARD_H / 2) - 0.06, 0.03);
  wrapper.add(edge);

  // soft radial contact shadow behind the tile (visual grounding)
  const shadowGeo = new PlaneGeometry(CARD_W * 1.4, CARD_H * 1.4, 1, 1);
  const uvC = uv().sub(vec2(0.5, 0.5));
  const falloff = smoothstep(float(0.5), float(0.0), length(uvC));
  const shadowMat = new MeshBasicNodeMaterial({
    color: new Color(colors.surface),
    transparent: true,
  });
  shadowMat.opacityNode = falloff.mul(float(0.45));
  const shadowPlane = new Mesh(shadowGeo, shadowMat);
  shadowPlane.position.z = -0.12;
  wrapper.add(shadowPlane);

  // ---------------------------------------------------------------
  // LOCAL LIGHTING — rim light carrying the accent hue (<=1.5)
  // ---------------------------------------------------------------
  const rimLight = new DirectionalLight(new Color(colors.accent), 0.7);
  rimLight.position.set(-0.6, 0.5, 1.1);
  wrapper.add(rimLight);

  // ---------------------------------------------------------------
  // CINEMATIC PRIMITIVES (from config.cinematicPrimitives ONLY)
  // ---------------------------------------------------------------
  const primitiveHandles = [];
  const primList = Array.isArray(config.cinematicPrimitives) ? config.cinematicPrimitives : [];
  for (const prim of primList) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      try {
        const handle = fn(parallaxMesh, prim.params || {});
        if (handle) primitiveHandles.push(handle);
      } catch (e) {
        // fail silently — never crash node creation on a primitive error
      }
    }
  }

  // ---------------------------------------------------------------
  // ENTRANCE — weighted-settle with subtle rise-in
  // ---------------------------------------------------------------
  wrapper.scale.setScalar(0.96);
  wrapper.position.y = -0.15;
  const entranceTl = gsap.timeline();
  entranceTl.to(wrapper.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
  entranceTl.to(wrapper.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.35, ease: 'power2.out' }, 0)
    .to(wrapper.scale, { x: 1, y: 1, z: 1, duration: 0.55, ease: 'power4.out' }, 0.35);

  // ---------------------------------------------------------------
  // INTERACTION STATE
  // ---------------------------------------------------------------
  let hovering = false;
  let pressed = false;
  const hoverTl = gsap.timeline({ paused: true });
  const pressTl = gsap.timeline({ paused: true });

  function hoverIn() {
    if (hovering) return;
    hovering = true;
    gsap.to(wrapper.position, { y: 0.15, duration: 0.3, ease: 'power2.out', overwrite: 'auto' });
    gsap.to(edgeMat, { opacity: 0.9, duration: 0.3, ease: 'power2.out', overwrite: 'auto' });
    gsap.to(rimLight, { intensity: 1.1, duration: 0.3, ease: 'power2.out', overwrite: 'auto' });
  }
  function hoverOut() {
    if (!hovering) return;
    hovering = false;
    gsap.to(wrapper.position, { y: 0, duration: 0.35, ease: 'power2.out', overwrite: 'auto' });
    gsap.to(edgeMat, { opacity: 0.28, duration: 0.35, ease: 'power2.out', overwrite: 'auto' });
    gsap.to(rimLight, { intensity: 0.7, duration: 0.35, ease: 'power2.out', overwrite: 'auto' });
  }
  function pressDown() {
    if (pressed) return;
    pressed = true;
    gsap.to(wrapper.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)', overwrite: 'auto' });
  }
  function pressUp() {
    if (!pressed) return;
    pressed = false;
    gsap.to(wrapper.scale, { x: 1, y: 1, z: 1, duration: 0.3, ease: 'power3.out', overwrite: 'auto' });
  }
  function onClick() {
    pressDown();
    gsap.delayedCall(0.12, pressUp);
    ctx.emit?.('hub-features.select', { nodeId: config.id || 'stat-tile-features' });
  }
  function onFocus() {
    hoverIn();
  }
  function onBlur() {
    hoverOut();
  }

  root.userData.handlers = {
    pointerenter: hoverIn,
    pointerleave: hoverOut,
    pointerdown: pressDown,
    pointerup: pressUp,
    click: onClick,
    focus: onFocus,
    blur: onBlur,
  };

  // ---------------------------------------------------------------
  // CLEANUP
  // ---------------------------------------------------------------
  root.userData.cleanup = () => {
    entranceTl.kill();
    hoverTl.kill();
    pressTl.kill();
    gsap.killTweensOf(wrapper.position);
    gsap.killTweensOf(wrapper.scale);
    gsap.killTweensOf(edgeMat);
    gsap.killTweensOf(rimLight);

    for (const handle of primitiveHandles) {
      try { handle.timeline?.kill?.(); } catch (e) {}
      try { handle.cleanup?.(); } catch (e) {}
    }

    plateGeo.dispose();
    plateMat.dispose();
    parallaxGeo.dispose();
    parallaxMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();

    placeholderColorTex.dispose();
    placeholderDepthTex.dispose();
    if (colorTexNode.value && colorTexNode.value !== placeholderColorTex) colorTexNode.value.dispose?.();
    if (depthTexNode.value && depthTexNode.value !== placeholderDepthTex) depthTexNode.value.dispose?.();

    rimLight.dispose?.();
  };

  return root;
}
